renderSoldMarkers(data){throw new TypeError(`${this.constructor.name}.renderSoldMarkers(data) must be implemented.`)}
clearSoldMarkers(){throw new TypeError(`${this.constructor.name}.clearSoldMarkers() must be implemented.`)}
reloadMarkers(filterUrl){if(!this.mapReady){return Promise.resolve()}
if(filterUrl){const url=this.createUrl(filterUrl);if(url){this.currentFilterUrl=url}}
return this.fetchMarkers()}
