class MapyMapLoader extends BaseMapLoader{map=null;markers=[];soldMarkers=[];markerCluster=null;categoryFilter=null;ensureScripts(resolve,reject){resolve()}
renderMap(){this.map=L.map(this.element.get(0));L.tileLayer(`//api.mapy.cz/v1/maptiles/basic/256/{z}/{x}/{y}?apikey=${this.apiKey}`,{minZoom:0,maxZoom:19,attribution:'<a href="https://api.mapy.cz/copyright" target="_blank">&copy; Seznam.cz a.s. a další</a>',}).addTo(this.map);const LogoControl=L.Control.extend({options:{position:'bottomleft',},onAdd:function(){const container=L.DomUtil.create('div');const link=L.DomUtil.create('a','',container);link.setAttribute('href','http://mapy.cz/');link.setAttribute('target','_blank');link.innerHTML='<img src="https://api.mapy.cz/img/api/logo.svg" />';L.DomEvent.disableClickPropagation(link);return container},});new LogoControl().addTo(this.map)}
setOptions(data){if(data.zoom){this.map.setZoom(data.zoom)}
if(data.center){this.map.panTo([data.center.lat,data.center.lng])}}
renderMarkers(data,clusterer,filter,fitBounds){if(this.markerCluster){this.map.removeLayer(this.markerCluster);this.markerCluster=null}
if(this.markers.length){this.markers.forEach(marker=>marker.remove())}
this.markers=[];this.categoryFilter?.off('change.mapFilter');if(filter&&filter.length){this.categoryFilter=filter;this.categoryFilter.find('option[data-map-category]').remove();this.categoryFilter.val('');this.categoryFilter.removeClass('uk-hidden')}else{this.categoryFilter=null}
const markers=[];const bounds=L.latLngBounds([]);const clusterGroup=L.markerClusterGroup();data.forEach(item=>{const customIcon=item.icon?L.divIcon({html:`<img src="${item.icon}" style="" />`,}):new L.Icon.Default();const marker=L.marker([item.position.lat,item.position.lng],{icon:customIcon}).addTo(this.map);marker.bindPopup(item.content,{maxWidth:300,offset:L.point([33,0])});marker.categories=item.categories;bounds.extend([item.position.lat,item.position.lng]);clusterGroup.addLayer(marker);markers.push(marker)});this.markers=markers;this.applyBounds(bounds,fitBounds,markers);if(this.categoryFilter){const categories=new Set();markers.forEach(marker=>{marker.categories?.forEach(category=>{if(!categories.has(category.name)){categories.add(category.name)}})});if(categories.size){categories.forEach(category=>{this.categoryFilter.append($('<option>').attr('data-map-category','1').text(category).val(category))});this.categoryFilter.on('change.mapFilter',event=>{const value=event.target.value;markers.forEach(marker=>{if(!value||(marker.categories?.some(category=>category.name===value)??!1)){marker.addTo(this.map)}else{marker.remove()}})})}else{this.categoryFilter.addClass('uk-hidden')}}
if(clusterer&&markers.length){this.markerCluster=clusterGroup;this.markerCluster.on('clusterclick',event=>{const clusterBounds=event.layer?.getBounds?.();const clusterMarkers=event.layer?.getAllChildMarkers?.()??[];if(clusterBounds){this.applyBounds(clusterBounds,!0,clusterMarkers)}});this.map.addLayer(this.markerCluster)}}
applyBounds(bounds,fitBounds,markers){if(!fitBounds||!markers.length||!bounds){return}
if(!bounds.isValid()){return}
const northEast=bounds.getNorthEast();const southWest=bounds.getSouthWest();if(northEast&&southWest&&northEast.equals(southWest)){this.map.setView(bounds.getCenter(),this.getSingleMarkerZoom());return}
this.map.fitBounds(bounds,{padding:this.getBoundsPadding()})}
getSingleMarkerZoom(){return 13}
getBoundsPadding(){return[60,60]}
renderLines(data){data.forEach(item=>{const latlngs=item.path.map(point=>[point.lat,point.lng]);L.polyline(latlngs,{color:item.strokeColor,weight:item.strokeWeight,opacity:item.strokeOpacity}).addTo(this.map)})}
renderSoldMarkers(data){this.clearSoldMarkers();data.forEach(item=>{const marker=L.circleMarker([item.position.lat,item.position.lng],{radius:8,fillColor:'#888888',fillOpacity:0.8,color:'#666666',weight:2,}).addTo(this.map);marker.bindPopup(item.content,{maxWidth:300,offset:L.point([0,-5])});this.soldMarkers.push(marker)})}
clearSoldMarkers(){if(this.soldMarkers.length){this.soldMarkers.forEach(marker=>marker.remove())}
this.soldMarkers=[]}};

